// Downloads the live Worker's modules + settings and writes sentinel/src/* and sentinel/wrangler.toml.
import { mkdirSync, writeFileSync } from 'node:fs';
const { CF_TOKEN, CF_ACCOUNT, SCRIPT } = process.env;
const api = p => `https://api.cloudflare.com/client/v4/accounts/${CF_ACCOUNT}/workers/scripts/${SCRIPT}${p}`;
const H = { Authorization: `Bearer ${CF_TOKEN}` };
const must = async r => { if (!r.ok) throw new Error(`${r.url} → HTTP ${r.status}: ${(await r.text()).slice(0, 300)}`); return r; };

const content = await must(await fetch(api('/content/v2'), { headers: H }));
const entry = content.headers.get('cf-entrypoint') || 'worker.js';
const ct = content.headers.get('content-type') || '';
mkdirSync('sentinel/src', { recursive: true });
let mainModule = entry;
if (ct.startsWith('multipart/form-data')) {
  const form = await content.formData();
  for (const [name, part] of form.entries()) {
    const file = typeof part === 'string' ? null : part;
    const fname = file ? (file.name || name) : name;
    const text = file ? await file.text() : part;
    if (fname.includes('..')) throw new Error('unsafe filename ' + fname);
    writeFileSync(`sentinel/src/${fname}`, text);
    console.log('module', fname, text.length, 'bytes');
  }
} else {
  writeFileSync(`sentinel/src/${entry}`, await content.text());
}
const settings = (await (await must(await fetch(api('/settings'), { headers: H }))).json()).result;
const schedules = (await (await must(await fetch(api('/schedules'), { headers: H }))).json()).result.schedules || [];
const kv = settings.bindings.filter(b => b.type === 'kv_namespace');
const secrets = settings.bindings.filter(b => b.type === 'secret_text').map(b => b.name);
const vars = settings.bindings.filter(b => b.type === 'plain_text');
const other = settings.bindings.filter(b => !['kv_namespace', 'secret_text', 'plain_text'].includes(b.type));
if (other.length) console.log('::warning::unhandled binding types:', other.map(b => b.type).join(','));
const toml = [
  `# Generated by sentinel-import from the live Worker. Secrets (${secrets.join(', ') || 'none'}) stay in Cloudflare and are never stored here.`,
  `name = "${SCRIPT}"`,
  `main = "src/${mainModule}"`,
  `compatibility_date = "${settings.compatibility_date}"`,
  settings.compatibility_flags?.length ? `compatibility_flags = ${JSON.stringify(settings.compatibility_flags)}` : '',
  `workers_dev = true`,
  '',
  '[observability]',
  `enabled = ${!!settings.observability?.enabled}`,
  `head_sampling_rate = ${settings.observability?.head_sampling_rate ?? 1}`,
  '',
  '[triggers]',
  `crons = ${JSON.stringify(schedules.map(s => s.cron))}`,
  '',
  ...kv.flatMap(b => ['[[kv_namespaces]]', `binding = "${b.name}"`, `id = "${b.namespace_id}"`, '']),
  ...(vars.length ? ['[vars]', ...vars.map(v => `${v.name} = ${JSON.stringify(v.text)}`), ''] : [])
].filter((l, i, a) => !(l === '' && a[i - 1] === '')).join('\n');
writeFileSync('sentinel/wrangler.toml', toml + '\n');
writeFileSync('sentinel/README.md', `# SENTINEL (Cloudflare Worker)\n\nSource of \`${SCRIPT}\`, imported from the live Worker. Deployed by \`.github/workflows/sentinel-deploy.yml\` when changes to \`sentinel/\` are merged to \`main\`.\n\nSecrets used (set in Cloudflare, never committed): ${secrets.map(s => '`' + s + '`').join(', ') || 'none'}.\n`);
console.log('entry', mainModule, '| kv', kv.map(b => b.name), '| secrets', secrets, '| crons', schedules.map(s => s.cron));
